def is_rectangle(grid, comp):
    """Check if component forms a perfect rectangle"""
    rows = set()
    cols = set()
    for r, c in comp:
        rows.add(r)
        cols.add(c)

    if not rows or not cols:
        return True

    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)

    expected_count = (max_r - min_r + 1) * (max_c - min_c + 1)
    return len(comp) == expected_count

def is_rectangular(grid, color):
    """Check if all FG components are rectangular"""
    comps = find_4_comps(grid, color)
